import zipfile
from lxml import etree
f='documents/turn-2-redline-meridian.docx'
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with zipfile.ZipFile(f) as z: root=etree.fromstring(z.read('word/document.xml'))
for i,p in enumerate(root.xpath('.//w:body/w:p',namespaces=ns),1):
    ins=p.xpath('./w:ins',namespaces=ns); dele=p.xpath('./w:del',namespaces=ns)
    if ins or dele:
        def tx(el,delx=False):
            return ''.join(el.xpath('.//w:delText/text()' if delx else './/w:t/text()',namespaces=ns))
        print('\nP',i,'style=',p.xpath('string(./w:pPr/w:pStyle/@w:val)',namespaces=ns))
        for d in dele: print(' DEL:',repr(tx(d,True)))
        for q in ins: print(' INS:',repr(tx(q)))
PY","description":"Enumerate all Turn 2 tracked changes"}

